   416→        [MethodImpl(MethodImplOptions.NoInlining)]
   417→        private static void EnhanceException(ReadOnlySpan<byte> rawKey, ValueHash256 rootHash, TrieException baseException)
   418→        {
   419→            static TrieNodeException? GetTrieNodeException(TrieException? exception) =>
   420→                exception switch
   421→                {
   422→                    null => null,
   423→                    TrieNodeException ex => ex,
   424→                    _ => GetTrieNodeException(exception.InnerException as TrieException)
   425→                };
   426→
   427→            TrieNodeException? trieNodeException = GetTrieNodeException(baseException);
   428→            if (trieNodeException is not null)
   429→            {
   430→                trieNodeException.EnhancedMessage = trieNodeException.NodeHash == rootHash
   431→                    ? $"Failed to load root hash {rootHash} while loading key {rawKey.ToHexString()}."
