   473→
   474→            _writeBeforeCommit++;
   475→
   476→            try
   477→            {
   478→                int nibblesCount = 2 * rawKey.Length;
   479→                byte[] array = null;
   480→                Span<byte> nibbles = (rawKey.Length <= MaxKeyStackAlloc
   481→                        ? stackalloc byte[MaxKeyStackAlloc] // Fixed size stack allocation
   482→                        : array = ArrayPool<byte>.Shared.Rent(nibblesCount))
   483→                    [..nibblesCount]; // Slice to exact size
   484→
   485→                Nibbles.BytesToNibbleBytes(rawKey, nibbles);
   486→
   487→                if (_traverseStack is null) _traverseStack = new Stack<TraverseStack>();
   488→                else if (_traverseStack.Count > 0) _traverseStack.Clear();
   489→
