   526→        private TrieNode? SetNew(Stack<TraverseStack> traverseStack, Span<byte> remainingKey, SpanSource value, ref TreePath path, TrieNode? node)
   527→        {
   528→            TrieNode? originalNode = node;
   529→            int originalPathLength = path.Length;
   530→
   531→            while (true)
   532→            {
   533→                if (node is null)
   534→                {
   535→                    node = value.IsNullOrEmpty ? null : TrieNodeFactory.CreateLeaf(remainingKey.ToArray(), value);
   536→
   537→                    // End traverse
   538→                    break;
   539→                }
   540→
   541→                node.ResolveNode(TrieStore, path);
   542→
   543→                if (node.IsLeaf || node.IsExtension)
   544→                {
   545→                    int commonPrefixLength = remainingKey.CommonPrefixLength(node.Key);
   546→                    if (commonPrefixLength == node.Key!.Length)
   547→                    {
   548→                        if (node.IsExtension)
   549→                        {
   550→                            // Continue traversal to the child of the extension
   551→                            path.AppendMut(node.Key);
   552→                            TrieNode? extensionChild = node.GetChildWithChildPath(TrieStore, ref path, 0);
   553→
   554→                            traverseStack.Push(new TraverseStack()
   555→                            {
   556→                                Node = node,
   557→                                OriginalChild = extensionChild,
   558→                                ChildIdx = 0,
   559→                            });
   560→
   561→                            // Continue loop with the child as current node
   562→                            remainingKey = remainingKey[node!.Key.Length..];
   563→                            node = extensionChild;
   564→
   565→                            continue;
   566→                        }
   567→
   568→                        if (value.IsNullOrEmpty)
   569→                        {
   570→                            // Deletion
   571→                            node = null;
   572→                        }
   573→                        else if (node.Value.Equals(value))
   574→                        {
   575→                            // SHORTCUT!
   576→                            path.TruncateMut(originalPathLength);
   577→                            traverseStack.Clear();
   578→                            return originalNode;
   579→                        }
   580→                        else if (node.IsSealed)
   581→                        {
   582→                            node = node.CloneWithChangedValue(value);
   583→                        }
   584→                        else
   585→                        {
   586→                            node.Value = value;
   587→                            node.Keccak = null; // For parent node usually done in SetChild.
   588→                        }
   589→
   590→                        // end traverse
   591→                        break;
   592→                    }
   593→
   594→                    // We are suppose to create a branch, but no change in structure
   595→                    if (value.IsNullOrEmpty)
   596→                    {
   597→                        // SHORTCUT!
   598→                        path.TruncateMut(originalPathLength);
   599→                        traverseStack.Clear();
   600→                        return originalNode;
   601→                    }
   602→
   603→                    // Making a T branch here.
   604→                    // If the commonPrefixLength > 0, we'll also need to also make an extension in front of the branch.
   605→                    TrieNode theBranch = TrieNodeFactory.CreateBranch();
   606→
   607→                    // This is the current node branch
   608→                    int currentNodeNib = node.Key[commonPrefixLength];
   609→                    if (node.Key.Length == commonPrefixLength + 1 && node.IsExtension)
   610→                    {
   611→                        // Collapsing the extension, taking the child directly and set the branch
   612→                        int originalLength = path.Length;
   613→                        path.AppendMut(node.Key);
   614→                        theBranch[currentNodeNib] = node.GetChildWithChildPath(TrieStore, ref path, 0);
   615→                        path.TruncateMut(originalLength);
   616→                    }
   617→                    else
   618→                    {
   619→                        // Note: could be a leaf at the end of the tree which now have zero length key
   620→                        theBranch[currentNodeNib] = node.CloneWithChangedKey(node.Key.Slice(commonPrefixLength + 1));
   621→                    }
   622→
   623→                    // This is the new branch
   624→                    theBranch[remainingKey[commonPrefixLength]] =
   625→                        TrieNodeFactory.CreateLeaf(remainingKey[(commonPrefixLength + 1)..].ToArray(), value);
   626→
   627→                    // Extension in front of the branch
   628→                    node = commonPrefixLength == 0 ?
   629→                        theBranch :
   630→                        TrieNodeFactory.CreateExtension(remainingKey[..commonPrefixLength].ToArray(), theBranch);
   631→
   632→                    break;
   633→                }
   634→
   635→                int nib = remainingKey[0];
   636→                path.AppendMut(nib);
   637→                TrieNode? child = node.GetChildWithChildPath(TrieStore, ref path, nib);
   638→
   639→                traverseStack.Push(new TraverseStack()
   640→                {
   641→                    Node = node,
   642→                    OriginalChild = child,
   643→                    ChildIdx = nib,
   644→                });
   645→
   646→                // Continue loop with child as current node
   647→                node = child;
   648→                remainingKey = remainingKey[1..];
   649→            }
   650→
   651→            while (traverseStack.TryPop(out TraverseStack cStack))
   652→            {
   653→                TrieNode? child = node;
   654→                node = cStack.Node;
   655→
   656→                if (node.IsExtension)
   657→                {
   658→                    path.TruncateMut(path.Length - node.Key!.Length);
   659→
   660→                    if (ShouldUpdateChild(node, cStack.OriginalChild, child))
   661→                    {
   662→                        if (child is null)
   663→                        {
   664→                            node = null; // Remove extension
   665→                            continue;
   666→                        }
   667→
   668→                        if (child.IsExtension || child.IsLeaf)
   669→                        {
   670→                            // Merge current node with child
   671→                            node = child.CloneWithChangedKey(Bytes.Concat(node.Key, child.Key));
   672→                        }
   673→                        else
   674→                        {
   675→                            if (node.IsSealed) node = node.Clone();
   676→                            node.SetChild(0, child);
   677→                        }
   678→                    }
   679→
   680→                    continue;
   681→                }
   682→
   683→                // Branch only
   684→                int nib = cStack.ChildIdx;
   685→
   686→                bool hasRemove = false;
   687→                path.TruncateOne();
   688→
   689→                if (ShouldUpdateChild(node, cStack.OriginalChild, child))
   690→                {
   691→                    if (child is null) hasRemove = true;
   692→                    if (node.IsSealed) node = node.Clone();
   693→
   694→                    node.SetChild(nib, child);
   695→                }
   696→
   697→                if (!hasRemove)
   698→                {
   699→                    // 99%
   700→                    continue;
   701→                }
   702→
   703→                // About 1% reach here
   704→                node = MaybeCombineNode(ref path, node);
   705→            }
   706→
   707→            return node;
   708→        }
   709→
   710→        internal bool ShouldUpdateChild(TrieNode parent, TrieNode? oldChild, TrieNode? newChild)
   711→        {
   712→            if (oldChild is null && newChild is null) return false;
   713→            if (!ReferenceEquals(oldChild, newChild)) return true;
   714→            if (newChild.Keccak is null && parent.Keccak is not null) return true; // So that recalculate root knows to recalculate the parent root.
   715→            return false;
   716→        }
   717→
   718→        /// <summary>
   719→        /// Tries to make the current node an extension or null if it has only one child left.
   720→        /// </summary>
   721→        /// <param name="path"></param>
   722→        /// <param name="node"></param>
   723→        /// <returns></returns>
   724→        internal TrieNode? MaybeCombineNode(ref TreePath path, in TrieNode? node)
   725→        {
   726→            int onlyChildIdx = -1;
   727→            TrieNode? onlyChildNode = null;
   728→            path.AppendMut(0);
   729→            var iterator = node.CreateChildIterator();
   730→            for (int i = 0; i < TrieNode.BranchesCount; i++)
   731→            {
   732→                path.SetLast(i);
   733→                TrieNode? child = iterator.GetChildWithChildPath(TrieStore, ref path, i);
   734→
   735→                if (child is not null)
   736→                {
   737→                    if (onlyChildIdx == -1)
   738→                    {
   739→                        onlyChildIdx = i;
   740→                        onlyChildNode = child;
   741→                    }
   742→                    else
   743→                    {
   744→                        // 63%
   745→                        // More than one non null child. We don't care anymore.
   746→                        path.TruncateOne();
   747→                        return node;
   748→                    }
   749→                }
   750→
   751→            }
   752→            path.TruncateOne();
   753→
   754→            if (onlyChildIdx == -1) return null; // No child at all.
   755→
   756→            path.AppendMut(onlyChildIdx);
   757→            onlyChildNode.ResolveNode(TrieStore, path);
   758→            path.TruncateOne();
   759→
   760→            if (onlyChildNode.IsBranch)
   761→            {
   762→                return TrieNodeFactory.CreateExtension([(byte)onlyChildIdx], onlyChildNode);
   763→            }
   764→
   765→            // 35%
   766→            // Replace the only child with something with extra key.
   767→            byte[] newKey = Bytes.Concat((byte)onlyChildIdx, onlyChildNode.Key);
   768→            TrieNode tn = onlyChildNode.CloneWithChangedKey(newKey);
   769→            return tn;
   770→        }
   771→
   772→        private record struct TraverseStack
   773→        {
   774→            public TrieNode Node;
   775→            public int ChildIdx;
   776→            public TrieNode? OriginalChild;
   777→        }
   778→
   779→        private SpanSource GetNew(Span<byte> remainingKey, ref TreePath path, TrieNode? node, bool isNodeRead)
   780→        {
   781→            int originalPathLength = path.Length;
   782→
   783→            try
   784→            {
   785→                while (true)
   786→                {
   787→                    if (node is null)
   788→                    {
   789→                        // If node read, then missing node. If value read.... what is it suppose to be then?
   790→                        return default;
   791→                    }
   792→
   793→                    node.ResolveNode(TrieStore, path);
   794→
   795→                    if (isNodeRead && remainingKey.Length == 0)
   796→                    {
   797→                        return node.FullRlp;
   798→                    }
   799→
   800→                    if (node.IsLeaf || node.IsExtension)
   801→                    {
   802→                        int commonPrefixLength = remainingKey.CommonPrefixLength(node.Key);
   803→                        if (commonPrefixLength == node.Key!.Length)
   804→                        {
   805→                            if (node.IsLeaf)
   806→                            {
   807→                                if (!isNodeRead && commonPrefixLength == remainingKey.Length) return node.Value;
   808→
   809→                                // Um..... leaf cannot have child
   810→                                return default;
   811→                            }
   812→
   813→                            // Continue traversal to the child of the extension
   814→                            path.AppendMut(node.Key);
   815→                            TrieNode? extensionChild = node.GetChildWithChildPath(TrieStore, ref path, 0);
   816→                            remainingKey = remainingKey[node!.Key.Length..];
   817→                            node = extensionChild;
   818→
   819→                            continue;
   820→                        }
   821→
   822→                        // No node match
   823→                        return default;
   824→                    }
   825→
   826→                    int nib = remainingKey[0];
   827→                    path.AppendMut(nib);
   828→                    TrieNode? child = node.GetChildWithChildPath(TrieStore, ref path, nib);
   829→
   830→                    // Continue loop with child as current node
   831→                    node = child;
   832→                    remainingKey = remainingKey[1..];
   833→                }
   834→            }
   835→            finally
   836→            {
   837→                path.TruncateMut(originalPathLength);
   838→            }
   839→        }
   840→
   841→        /// <summary>
   842→        /// Run tree visitor
   843→        /// </summary>
   844→        /// <param name="visitor">The visitor</param>
   845→        /// <param name="rootHash">State root hash (not storage root)</param>
   846→        /// <param name="visitingOptions">Options</param>
   847→        /// <param name="storageAddr">Address of storage, if it should visit storage. </param>
   848→        /// <param name="storageRoot">Root of storage if it should visit storage. Optional for performance.</param>
   849→        /// <typeparam name="TNodeContext"></typeparam>
   850→        public void Accept<TNodeContext>(
   851→            ITreeVisitor<TNodeContext> visitor,
   852→            Hash256 rootHash,
   853→            VisitingOptions? visitingOptions = null,
   854→            Hash256? storageAddr = null,
   855→            Hash256? storageRoot = null
   856→        ) where TNodeContext : struct, INodeContext<TNodeContext>
   857→        {
   858→            ArgumentNullException.ThrowIfNull(visitor);
   859→            ArgumentNullException.ThrowIfNull(rootHash);
   860→            visitingOptions ??= VisitingOptions.Default;
   861→
   862→            using TrieVisitContext trieVisitContext = new()
   863→            {
   864→                MaxDegreeOfParallelism = visitingOptions.MaxDegreeOfParallelism,
   865→                IsStorage = storageAddr is not null
   866→            };
   867→
   868→            if (storageAddr is not null)
   869→            {
   870→                Hash256 DecodeStorageRoot(Hash256 root, Hash256 address)
   871→                {
   872→                    ReadOnlySpan<byte> bytes = Get(address.Bytes, root);
   873→                    Rlp.ValueDecoderContext valueContext = bytes.AsRlpValueContext();
   874→                    return AccountDecoder.Instance.DecodeStorageRootOnly(ref valueContext);
   875→                }
   876→
   877→                rootHash = storageRoot ?? DecodeStorageRoot(rootHash, storageAddr);
   878→            }
   879→
   880→            ReadFlags flags = visitor.ExtraReadFlag;
   881→            if (visitor.IsFullDbScan)
   882→            {
   883→                if (TrieStore.Scheme == INodeStorage.KeyScheme.HalfPath)
   884→                {
   885→                    // With halfpath or flat, the nodes are ordered so readahead will make things faster.
   886→                    flags |= ReadFlags.HintReadAhead;
   887→                }
   888→                else
   889→                {
   890→                    // With hash, we don't wanna add cache as that will take some CPU time away.
   891→                    flags |= ReadFlags.HintCacheMiss;
   892→                }
   893→            }
   894→
   895→            ITrieNodeResolver resolver = flags != ReadFlags.None
   896→                ? new TrieNodeResolverWithReadFlags(TrieStore, flags)
   897→                : TrieStore;
   898→
   899→            if (storageAddr is not null)
   900→            {
   901→                resolver = resolver.GetStorageTrieNodeResolver(storageAddr);
   902→            }
   903→
   904→            bool TryGetRootRef(out TrieNode? rootRef)
   905→            {
   906→                rootRef = null;
   907→                if (rootHash != Keccak.EmptyTreeHash)
   908→                {
   909→                    TreePath emptyPath = TreePath.Empty;
   910→                    rootRef = RootHash == rootHash ? RootRef : resolver.FindCachedOrUnknown(emptyPath, rootHash);
   911→                    if (!rootRef!.TryResolveNode(resolver, ref emptyPath))
   912→                    {
   913→                        visitor.VisitMissingNode(default, rootHash);
   914→                        return false;
   915→                    }
   916→                }
   917→
   918→                return true;
   919→            }
   920→
   921→            if (!visitor.IsFullDbScan)
   922→            {
   923→                visitor.VisitTree(default, rootHash);
   924→                if (TryGetRootRef(out TrieNode rootRef))
   925→                {
   926→                    TreePath emptyPath = TreePath.Empty;
   927→                    rootRef?.Accept(visitor, default, resolver, ref emptyPath, trieVisitContext);
   928→                }
   929→            }
   930→            // Full db scan
   931→            else if (TrieStore.Scheme == INodeStorage.KeyScheme.Hash && visitingOptions.FullScanMemoryBudget != 0)
   932→            {
   933→                visitor.VisitTree(default, rootHash);
   934→                BatchedTrieVisitor<TNodeContext> batchedTrieVisitor = new(visitor, resolver, visitingOptions);
   935→                batchedTrieVisitor.Start(rootHash, trieVisitContext);
   936→            }
   937→            else if (TryGetRootRef(out TrieNode rootRef))
   938→            {
   939→                TreePath emptyPath = TreePath.Empty;
   940→                visitor.VisitTree(default, rootHash);
   941→                rootRef?.Accept(visitor, default, resolver, ref emptyPath, trieVisitContext);
   942→            }
   943→        }
   944→
   945→        [DoesNotReturn, StackTraceHidden]
   946→        static void ThrowReadOnlyTrieException() => throw new TrieException("Commits are not allowed on this trie.");
   947→
   948→        [DoesNotReturn, StackTraceHidden]
   949→        private static void ThrowInvalidDataException(TrieNode originalNode)
   950→        {
   951→            throw new InvalidDataException(
   952→                $"Extension {originalNode.Keccak} has no child.");
   953→        }
   954→
   955→        [DoesNotReturn, StackTraceHidden]
   956→        private static void ThrowMissingChildException(TrieNode node)
   957→        {
   958→            throw new TrieException(
   959→                $"Found an {nameof(NodeType.Extension)} {node.Keccak} that is missing a child.");
   960→        }
   961→
   962→        [DoesNotReturn, StackTraceHidden]
   963→        private static void ThrowMissingPrefixException()
   964→        {
   965→            throw new InvalidDataException("An attempt to visit a node without a prefix path.");
   966→        }
   967→    }
   968→}
   969→

